ArchVSpace_H.ARM_H.deleteASIDPool_def ARM_H.deleteASIDPool ?base ?ptr \<equiv>
do haskell_assert (?base && mask ARM_H.asidLowBits = 0) [];
   asidTable <- gets (ARM_H.armKSASIDTable \<circ> ksArchState);
   when (asidTable (ARM_H.asidHighBitsOf ?base) = Just ?ptr) $
   do pool <- liftM (inv ARM_H.ASIDPool) $ getObject ?ptr;
      forM [0 .e. HaskellLib_H.bit ARM_H.asidLowBits - 1]
       (\<lambda>offset.
           when (isJust $ pool offset) $
           do ARM_H.flushSpace $ ?base + offset;
              ARM_H.invalidateASIDEntry $ ?base + offset
           od);
      asidTable' <-
      return (asidTable aLU [(ARM_H.asidHighBitsOf ?base, Nothing)]);
      modify
       (\<lambda>s. s
           \<lparr>ksArchState :=
                     ARM_H.armKSASIDTable_update (\<lambda>_. asidTable')
                      (ksArchState s)\<rparr>);
      getCurThread >>= ARM_H.setVMRoot
   od
od
Endpoint_H.cancelIPC_def__internal__ cancelIPC ?tptr \<equiv>
let replyIPCCancel =
      do threadSet (tcbFault_update (\<lambda>_. Nothing)) ?tptr;
         slot <- getThreadReplySlot ?tptr;
         callerCap <- liftM (mdbNext \<circ> cteMDBNode) $ getCTE slot;
         when (callerCap \<noteq> nullPointer) $
         do stateAssert
             (capHasProperty callerCap
               (\<lambda>cap.
                   isReplyCap cap \<and> \<not> capReplyMaster cap))
             [];
            cteDeleteOne callerCap
         od
      od;
    isIdle =
      \<lambda>ep.
         case ep of Structures_H.endpoint.IdleEP \<Rightarrow> True
         | _ \<Rightarrow> False;
    blockedIPCCancel =
      \<lambda>state.
         do epptr <- return (blockingObject state);
            ep <- getEndpoint epptr;
            haskell_assert (Not $ isIdle ep) [];
            queue' <- return (delete ?tptr $ epQueue ep);
            ep' <-
            case queue' of
            [] \<Rightarrow> return Structures_H.endpoint.IdleEP
            | a # list \<Rightarrow>
                return $ epQueue_update (\<lambda>_. queue') ep;
            setEndpoint epptr ep';
            setThreadState Structures_H.thread_state.Inactive ?tptr
         od
in do state <- getThreadState ?tptr;
      case state of
      Structures_H.thread_state.BlockedOnReceive x xa \<Rightarrow>
        blockedIPCCancel state
      | Structures_H.thread_state.BlockedOnReply \<Rightarrow>
          replyIPCCancel
      | Structures_H.thread_state.BlockedOnNotification x \<Rightarrow>
          cancelSignal ?tptr (waitingOnNotification state)
      | Structures_H.thread_state.BlockedOnSend x xa xb xc xd \<Rightarrow>
          blockedIPCCancel state
      | _ \<Rightarrow> return ()
   od
