   state <- getThreadState thread;
   case state of Structures_H.thread_state.Running \<Rightarrow> return ()
   | Structures_H.thread_state.IdleThreadState \<Rightarrow>
       Arch.activateIdleThread thread
   | Structures_H.thread_state.Restart \<Rightarrow>
       do pc <- asUser thread $ getRestartPC;
