ArchVSpace_H.ARM_H.decodeARMPageFlush_def ARM_H.decodeARMPageFlush ?label ?args ?cap \<equiv>
case (?args, ARM_H.capVPMappedAddress ?cap) of
([], b) \<Rightarrow> throw Fault_H.syscall_error.TruncatedMessage
| ([start], b) \<Rightarrow> throw Fault_H.syscall_error.TruncatedMessage
| (start # end # x, None) \<Rightarrow>
    throw Fault_H.syscall_error.IllegalOperation
| (start # end # x, Some (asid, vaddr)) \<Rightarrow>
    doE pd <- lookupErrorOnFailure False $ ARM_H.findPDForASID asid;
        whenE (end \<le> start) $
        throw $ Fault_H.syscall_error.InvalidArgument 1;
        pageSize <-
        returnOk
         (HaskellLib_H.bit (ARM.pageBitsForSize (ARM_H.capVPSize ?cap)));
        pageBase <- returnOk (addrFromPPtr $ ARM_H.capVPBasePtr ?cap);
        whenE (pageSize \<le> start \<or> pageSize < end) $
        throw $ Fault_H.syscall_error.InvalidArgument 0;
        pstart <- returnOk (pageBase + id start);
        start' <- returnOk (start + fromVPtr vaddr);
        end' <- returnOk (end + fromVPtr vaddr);
        returnOk $
        ARM_H.InvokePage $
        ARM_H.PageFlush (ARM_H.labelToFlushType ?label) (VPtr $ start')
         (VPtr $ end' - 1) pstart pd asid
    odE
