Thread_H.doReplyTransfer_def doReplyTransfer ?sender ?receiver ?slot ?grant \<equiv>
do state <- getThreadState ?receiver;
   haskell_assert (isReply state) [];
   mdbNode <- liftM cteMDBNode $ getCTE ?slot;
   haskell_assert
    (mdbPrev mdbNode \<noteq> nullPointer \<and>
     mdbNext mdbNode = nullPointer)
    [];
   parentCap <- getSlotCap (mdbPrev mdbNode);
   haskell_assert (isReplyCap parentCap \<and> capReplyMaster parentCap) [];
   fault <- threadGet tcbFault ?receiver;
   case fault of
   None \<Rightarrow>
     do doIPCTransfer ?sender Nothing 0 ?grant ?receiver;
        cteDeleteOne ?slot;
        setThreadState Structures_H.thread_state.Running ?receiver;
        possibleSwitchTo ?receiver
     od
   | Some f \<Rightarrow>
       do cteDeleteOne ?slot;
          tag <- getMessageInfo ?sender;
          sendBuffer <- lookupIPCBuffer False ?sender;
          mrs <- getMRs ?sender sendBuffer tag;
          restart <- handleFaultReply f ?receiver (msgLabel tag) mrs;
          threadSet (tcbFault_update (\<lambda>_. Nothing)) ?receiver;
          if restart
          then do setThreadState Structures_H.thread_state.Restart
                   ?receiver;
                  possibleSwitchTo ?receiver
               od
          else setThreadState Structures_H.thread_state.Inactive ?receiver
       od
od
Schedule_A.schedule_def state_ext_sched_class.schedule \<equiv>
do ct <- gets cur_thread;
   ct_st <- get_thread_state ct;
   ct_runnable <- return $ runnable ct_st;
   action <- gets scheduler_action;
   case action of
   resume_cur_thread \<Rightarrow> do id <- gets idle_thread;
assert (ct_runnable \<or> ct = id);
return ()
                                   od
   | switch_thread candidate \<Rightarrow>
       do when ct_runnable (tcb_sched_action tcb_sched_enqueue ct);
          it <- gets idle_thread;
          target_prio <- ethread_get tcb_priority candidate;
          ct_prio <- ethread_get_when (ct \<noteq> it) tcb_priority ct;
          fastfail <-
          schedule_switch_thread_fastfail ct it ct_prio target_prio;
          cur_dom <- gets cur_domain;
          highest <- gets (is_highest_prio cur_dom target_prio);
          if fastfail \<and> \<not> highest
          then do tcb_sched_action tcb_sched_enqueue candidate;
                  set_scheduler_action choose_new_thread;
                  schedule_choose_new_thread
               od
          else if ct_runnable \<and> ct_prio = target_prio
               then do tcb_sched_action tcb_sched_append candidate;
                       set_scheduler_action choose_new_thread;
                       schedule_choose_new_thread
                    od
               else do guarded_switch_to candidate;
                       set_scheduler_action resume_cur_thread
                    od
       od
   | choose_new_thread \<Rightarrow>
       do when ct_runnable (tcb_sched_action tcb_sched_enqueue ct);
          schedule_choose_new_thread
       od
od
ArchRetype_H.ARM_H.finaliseCap_def Arch.finaliseCap ?x0.0 ?x1.0 \<equiv>
let (cap, bl) = (?x0.0, ?x1.0)
in if ARM_H.isASIDPoolCap cap \<and> bl
   then let b = ARM_H.capASIDBase cap; ptr = ARM_H.capASIDPool cap
        in do ARM_H.deleteASIDPool b ptr;
              return (capability.NullCap, capability.NullCap)
           od
   else if ARM_H.isPageDirectoryCap cap \<and>
           bl \<and> ARM_H.capPDMappedASID cap \<noteq> None
        then let a = the (ARM_H.capPDMappedASID cap);
                 ptr = ARM_H.capPDBasePtr cap
             in do ARM_H.deleteASID a ptr;
                   return (capability.NullCap, capability.NullCap)
                od
        else if ARM_H.isPageTableCap cap \<and>
                bl \<and> ARM_H.capPTMappedAddress cap \<noteq> None
             then let (a, v) = the (ARM_H.capPTMappedAddress cap);
                      ptr = ARM_H.capPTBasePtr cap
                  in do ARM_H.unmapPageTable a v ptr;
                        return (capability.NullCap, capability.NullCap)
                     od
             else if ARM_H.isPageCap cap \<and>
                     ARM_H.capVPMappedAddress cap \<noteq> None
                  then let (a, v) = the (ARM_H.capVPMappedAddress cap);
                           s = ARM_H.capVPSize cap;
                           ptr = ARM_H.capVPBasePtr cap
                       in do ARM_H.unmapPage s a v ptr;
                             return (capability.NullCap, capability.NullCap)
                          od
                  else return (capability.NullCap, capability.NullCap)
